#include "cubic_field.hpp"
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: cubic_gcd factor-index resultants-directory");EF::init(std::stoi(argv[1]));std::string dir=argv[2];EP a=read_ep(dir+"/res0.bin"),b=read_ep(dir+"/res1.bin");if(a.empty()||b.empty())throw std::runtime_error("zero resultant");int va=0,vb=0;while(!a[va])va++;while(!b[vb])vb++;a.erase(a.begin(),a.begin()+va);b.erase(b.begin(),b.begin()+vb);EP aa=a,bb=b;std::cout<<"factor="<<EF::factor_index<<"; reduced resultant degrees="<<a.deg()<<","<<b.deg()<<"; removed H powers="<<va<<","<<vb<<"\n"<<std::flush;EP u{E(1)},v{},s{},z{E(1)};int steps=0;while(!b.empty()){auto[q,r]=epdiv(a,b);EP uu=u-q*s,vv=v-q*z;a=std::move(b);b=std::move(r);u=std::move(s);v=std::move(z);s=std::move(uu);z=std::move(vv);steps++;if(steps%2048==0)std::cout<<"Euclidean steps="<<steps<<"; remainder degree="<<b.deg()<<"\n"<<std::flush;}E iv=EF::inv(a.back());a=escale(a,iv);u=escale(u,iv);v=escale(v,iv);
// The exact full identity is checked independently by packed_cubic_verify.
// These extra evaluations detect serialization errors before that full check.
for(E h:{E(),E(1),E(25),E(0,1),E(25,1,1)})if(eeval(aa,h)*eeval(u,h)+eeval(bb,h)*eeval(v,h)!=eeval(a,h))throw std::runtime_error("Bezout diagnostic evaluation");
std::ofstream o(dir+"/gcd_certificate.json");o<<"{\"factor_index\":"<<EF::factor_index<<",\"H_valuations\":["<<va<<","<<vb<<"],\"reduced_resultant_degrees\":["<<aa.deg()<<","<<bb.deg()<<"],\"euclidean_steps\":"<<steps<<",\"gcd\":";json_ep(o,a);o<<",\"multipliers\":[";json_ep(o,u);o<<",";json_ep(o,v);o<<"],\"identity\":\"u*(res0/H^v0)+v*(res1/H^v1)=gcd\",\"verification\":\"full coefficient identity requires the independent packed verifier\"}\n";std::cout<<"gcd degree="<<a.deg()<<"; certificate saved; five bounded identity checks pass. Full independent coefficient verification is still required.\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
